public class Join {
  static String join(String[] words) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
      if (i > 0) sb.append(' ');
      sb.append(words[i]);
    }
    return sb.toString();
  }

  public static void main(String[] args) {
    System.out.println(join(new String[]{"a", "b", "c"}));
  }
}

