public class FindEven {
  static Optional<Integer> findFirstEven(int[] xs) {
    for (int x : xs) {
      if (x % 2 == 0) return Optional.of(x);
    }
    return Optional.empty();
  }

  public static void main(String[] args) {
    System.out.println(findFirstEven(new int[]{1, 3, 4, 5}).orElse(-1));
